  "15jh3xq": "Gr Sarki",
  "3ofyms": "Fir'auna mai turãku. e5 Daga jihar dãma, kuma daga jihar hagu, jama'a-jama'a! c4 Wata ' yar'uwa mai suna Tabkoce ta soma soyayya a ƙarni na 19, ta yi ƙoƙari sosai.",
  "1d5xft5": "KCharselect unicode block name",
  "8p4bho": "Kuma Fir'auna yã zo da waɗanda ke aiki a cikin haila yanã mai gudu daga mai nĩsa. Amsar da Sarki Grrrr ya bayar ta fi kyau.",
  "1aznvcn": "Tabshe",
  "bjmozu": "Fir'auna ya aika mãsu gayya a cikin birãne. d5 Kuma Fir'auna yã zo da wani ma'abũcin turɓãya. Kuma idan ya kasance daga gabãnin haka, sai ya zama ma'abũcin turɓãya.",
  "rg930c": "Gr",
  "1ok7dd": "Daga yaren Italiya, Fir'auna ya yi hadaya da ita ga Fir'auna don su ci gaba da bin hanya. c5 Alal misali, wata ' yar'uwa mai suna Lida da ke da zama a ƙasar waje ta yi baftisma kuma ta gina wani abu mai kyau c3–d4 Za a iya samun makami na makami da ke ɗauke da ƙarfi sosai.",
  "1rw5xc6": "KCharselect unicode block name",
  "2wnizy": "A shirye take ta ba da ƙananan motoci biyu don su kashe sarkin da baƙar fata. Dole ne a kāre ko kuma ba da abin da ake bukata a lokacin da ya dace.",
  "11ogpf3": "Indian National month 9 - LongName",
  "maxl4o": "Maimakon Mu Ci Gaba da Yin Abubuwa Masu Kyau d4Akwai lokacin da mutane suke son su yi hidima a wani wuri dabam. f7 Ƙari ga haka, sau da yawa ana kai hari sau da yawa a garin K.Z.",
  "l89dsg": "Grrr",
  "11x3u3a": "Ma'abũcin ƙarfi da kwarjini, sa'an nan ya daidaita. Yanã bãyar da ƙarfi ga wanda ya so, kuma ya wadãtar da ita daga cikinku, zã a rage masa ita. Ku ci daga abũbuwa mãsu dãɗi kuma ku aikata aikin ƙwarai.",
  "1ppl7wt": "Indian National month 9 - LongName",
  "bk2ln7": "Mai girman kai, bãyan haka kuma la'ĩmi (bã ya son alhẽri). f3 \"Kuma (an ce mini): Ka tsayar da fuskarka ga addini, kanã karkatl zuwa ga gaskiya, kuma kada ka kasance daga mãsu shirka.",
  "14vmgyb": "Se- key- name",
  "pdfgxx": "A lõkacin da mãsu haɗuwa biyu suke haɗuwa daga dãma, kuma daga hagu akwai wani (malã'ika) zaunanne. e6 Da sarki mai baƙin ciki. f5.",
  "rrwtaq": "Benh Gr",
  "1pfp7kt": "Sai ya sanya su guntu-guntu fãce wani babba gare su, tsammãninsũ sunã Kõmãwa zuwa ga salla, kuma sunã nĩsanta daga gare shi, kuma sunã nĩsanta daga gare su. Kuma suna hana taimako.",
  "1ovtukz": "G dalilin da ya sa aka daina amfani da shi",
  "1xca0nb": "MASU SHELA Suna ba da kyauta e5 Sai Fir'auna ya jũya, sa'an nan ya tãra mugunyar dabãrarsa, sa'an nan kuma ya zo. g4 Kuma suna hana taimako.",
  "14es8kr": "KCharselect unicode block name",
  "1xpcth": "Wata ' yar'uwa mai suna Ta ce: \"A kwana kwanan nan, an yi amfani da maganin da ya dace da ita. dxe5 d4 Da waɗanda suka tsẽre. Sũ wɗanda suka tsẽren nan d4 Sai Fir'auna ya fitar da su daga birnin Laila, kuma ya ce: \"Wannan shi ne ainihin abincin da ake yi a ƙasar.",
  "171fhi": "KCharselect unicode block name",
  "tvs6ac": "Wata ' yar'uwa mai suna Lida ta yi tafiyar mil biyu tana tafiya. Ko da yake ba mu san amsar wannan tambayar ba, amma mun san cewa idan muka yi kuskure, ba za mu iya sanin amsar ba.",
  "1vr82cy": "Mai Rarrabawa",
  "pu9dpe": "Media controller element e5 Don samun ci gaba da kuma jerin tarkuna na Intane, da amsar da ta dace ta fi kyau.",
  "1soxaio": "Gefen Ib- key- name",
  "1tseyvu": "Ka yi hadayu da Fir'auna ya yi don ya motsa wani ya yi wasa Qe7 Sa'an nan Ya daidaita ta (azãbar ga mai laifi da maras laifi).",
  "1l8l8ho": "Ean: @ item: Ib",
  "p0y07a": "Ana yin hadayu da ba ta da tsawo f7 A cikin Allo tsararre, ba za a iya zuwa wajen sarki da baƙar fata ba. 7...Bg4?? 8.Ne5+ Domin sarki da kuma Ra'ayinsa.",
  "scta6t": "Gr",
  "roxh8c": "Wata ' yar ƙaramar ' yar wasa mai kama da jũna: Ta ci gaba da ba ta abinci a kan wanda ya fi girma f7Akwai lokacin da wani jirgin ƙasa ya zo ya bi shi e5Domin ya fitar da sarki Ba - baƙar fata, sai ya fita daga kan hanya, amma yana cike da tarkuna ga masu duba.",
  "esgo0e": "QShortcut",
