  "1jqrv03": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 e6 2.d4 d5 3.e5. . e5 Dõmin su shiga wani wuri mai nĩsa. c5 @ action Qb6Mai twãle fãtar goshi. d4.",
  "16mv5rj": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 c6 2.d4 d5. . . . c8 Har ila, Fir'auna mai hikima ya tsara wasu kasawa, kuma hakan ya dace don ya ƙarfafa Isra'ilawa.",
  "5orj62": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 c6 2.d4 d5 3.e5 Bf5. L̃. e5Akwai lokacin da aka kai gidan Fir'auna mai suna Swa f5 \"Kuma lalle ne shi, wãwanmu ya kasance yana faɗar abin da ya ƙetare haddi ga Allah.\" e6. Su biyun sun yi shiri don su yi hakan.",
  "n6cxux": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 d5 2.exd5 Qxd5Ṣ̃. e4 Da take tafiya da sarauniyar, sarauniyar ta bi hanya mai sauƙi, amma a bayyane yake cewa shirin ya fita sarai.",
  "143sw39": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 Nf6 2.e5 Nd5. . . . . A lokacin, mutane suna iya yin amfani da filin wasa don su kai hari ga masu ruwan sama.",
  "15zkca2": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 d6 2.d4 Nf6 3.Nc3 g6@ item Spelling dictionary g7 Alhãli shĩ yanã jin tsõrõn Allah. c5 ko kuwa e5Mãsu kai-kawo ne a tsakãnin wancan; bã zuwa ga waɗannan ba, kuma bã zuwa ga waɗannan ba.",
  "vg41kr": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 g6 2.d4 Bg7. . . . g7 Da farko, ka mai da hankali ga abin da kake son ka yi g8 Ba a tilasta wa mutane su yi ƙarya, domin suna da ra'ayin da bai dace ba.",
  "m83jcz": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 c5 2.Nf3 Nc6 3.d4 cxd4 4.Nxd4 Nf6 5.Nc3 e5. . . . . e5 Don a rage filin wasan, ka amince da wanda ya raunana d5 Wani ɗan'uwa mai suna Agan da aka yi amfani da shi a wannan duniyar ya yi aiki na ɗan lokaci kuma ya yi aiki sosai.",
  "1xs0oks": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 c5 2.Nf3 Nc6 3.d4 cxd4 4.Nxd4 g6@ item Spelling dictionary d6Ka riƙe zaɓin...d5 A wata hanya, ka guje wa muguwar ma'aikata da ke kusa da inda ake yawan zuwa.",
  "14phitg": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 e6 2.d4 d5 3.Nc3 Bb4. . . c3 ' Yan kasuwa suna shirye su yi kasuwanci kuma su ɓata filin wasa da ake kira n, wanda shi ne ainihin hanyar yaren Faransa.",
  "edit0m": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 c6 2.d4 d5 3.Nc3 dxe4 4.Nxe4 Bf5A. L̃. M̃. f5 Alhãli kuwa yanã a sararin samã mafi aukaka. e6; ƙarfi: Mutane kaɗan ne kawai raunana da shirye - shirye.",
  "1647uir": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 c5 2.Nf3 d6 3.d4 cxd4 4.Nxd4 Nf6 5.Nc3 e6. . .d6 da kuma...e6Ka jira ka auko wa...d5 ko kuma a kan sarauniyar, sau da yawa ba a kai wa sarauniyar hari. g4 A'aha!",
  "w24am2": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 c5 2.Nf3 e6 3.d4 cxd4 4.Nxd4 Nc6. . .Nc6 Ka riƙa lura da Fir'auna mai jin ƙai...Qc7Ba don ya sa mutane su gaskata cewa akwai wani abu mai kyau kamar ruwa ba.",
  "h726lw": "Mai ƙwanƙwasar (zukata da tsõro)!1.e4Akwai abubuwa da ba za a iya guje wa ba e5Mãsu aikin wahala ne, mãsu gajiya. 1.e4 c5 2.Nf3 Nc6 3.Bb5. . . b5 Za a iya yin shiri don ɗaukan mataki c6 \"Kuma sunã da waɗansu amfãnõni a cikinsu, da abũbuwan shã.",
